	class HttpHeaderParserTest extends PHPUnit_Framework_TestCase
	{
		/**
		 * @var HttpHeaderParser
		 */
		protected $object = null;

		public function setUp()
		{
			$this->object = new HttpHeaderParser();
		}

		/**
		 * @covers HttpHeaderParser::getHeaders
		 */
		public function testGetHeaders()
		{
			$response = "HTTP/1.1 301 Moved Permanently\r\nServer: nginx\r\nDate: Mon, 25 Nov 2013 20:33:36 GMT\r\nContent-Type: text/html\r\nContent-Length: 178\r\nConnection: close\r\nLocation: http://www.tut.by/";

			$headers = $this->object->getHeaders($response);

			$this->assertInternalType('array', $headers);
			$this->assertCount(6, $headers);

			$this->assertTrue(isset($headers['Server']));
			$this->assertEquals('nginx', $headers['Server']);

			$this->assertTrue(isset($headers['Date']));
			$this->assertEquals('Mon, 25 Nov 2013 20:33:36 GMT', $headers['Date']);

			$this->assertTrue(isset($headers['Content-Type']));
			$this->assertEquals('text/html', $headers['Content-Type']);

			$this->assertTrue(isset($headers['Content-Length']));
			$this->assertEquals('178', $headers['Content-Length']);

			$this->assertTrue(isset($headers['Connection']));
			$this->assertEquals('close', $headers['Connection']);

			$this->assertTrue(isset($headers['Location']));
			$this->assertEquals('http://www.tut.by/', $headers['Location']);
		}

		public function testGetStatusCode()
		{
			$response = 'HTTP/1.1 301 Moved Permanently
Server: nginx
Date: Mon, 25 Nov 2013 20:33:36 GMT
Content-Type: text/html
Content-Length: 178
Connection: close
Location: http://www.tut.by/';

			$status_code = $this->object->getStatusCode($response);

			$this->assertEquals(301, $status_code);
		}
	}
